#!/bin/sh
#
# install.sh - Install the unified DTS + TrueHD/MLP audio restore on a rooted
#              LG webOS 25 TV (C5 class). PROVEN working on a real LG C5.
#
# Run as root ON THE TV, from this restore/ directory (copied via scp). For
# full DTS-HD/DTS:X to an eARC receiver instead of the DTS core: HD=1 sh install.sh
# The directory must contain:
#     out/libgstdtsdec.so        patched dtsdec (S32LE, accepts A_DTS;   [build.sh]
#                                FFmpeg's dca decoder linked in statically)
#     truehd-out/libgstlibav.so  gst-libav with avdec_truehd/avdec_mlp   [build-truehd.sh]
#     truehd-out/libav*.so*      minimal ffmpeg n4.4.4 libs (+symlinks)  [build-truehd.sh]
#     truehd-out/libsw*.so*      libswresample (+symlinks)               [build-truehd.sh]
#     switch-out/libgstadecswitch.so  same-family stream-switch bin (rank 320) [build-switch.sh]
#     edid-out/libedidaudio.so        keeps DTS out of the HDMI EDID (OPT.)  [build-edid.sh]
#     demux-out/libgstisomp4.so       mp4 demux, DTS re-enabled (OPTIONAL) [build-demux.sh]
#     demux-out/libgstmpegtsdemux.so  ts/m2ts demux, DTS re-enabled (OPT.) [build-demux.sh]
#     demux-out/libgstmatroska.so     mkv demux, Dolby Vision profile 7 (OPT.) [build-demux.sh]
#     demux-out/libgstmpegpsdemux.so  vob/MPEG-PS demux, DTS re-enabled (OPT.) [build-demux.sh]
#   (the boot/apply script is EMBEDDED in this installer - no sibling file needed)
#
# out/, truehd-out/ and switch-out/ are the CORE payload and are required.
# demux-out/ is optional: without it the boot hook simply skips the demuxer
# binds and DTS still works in MKV (see step 2c).
#
# All binaries are PREBUILT and bundled; you do NOT need Docker or to build
# anything. Just: copy this folder to the TV, then run (as root):
#
#   sh install.sh
#
# What it does (idempotent, guarded, logged to /tmp/dts25.log, always exit 0):
#   1. Stages the DTS payload  -> /var/lib/webosbrew/dts25/
#   2. Stages the TrueHD payload-> /var/lib/webosbrew/truehd/{,libs/}
#   2c. Stages the container demuxers (if demux-out/ present)
#        -> /var/lib/webosbrew/demux25/ (mp4/ts/m2ts DTS, MKV Dolby Vision P7;
#           boot hook binds them)
#   3. GENERATES two config overrides by EDITING the TV's own live /etc files
#      (no LG config file is shipped):
#        a. /etc/umediaserver/device_codec_capability_config.json
#           -> insert TRUEHD + MLP audio-codec objects after the DTSE entry
#        b. /etc/gst/gstcool.conf
#           -> insert avdec_truehd=310 + avdec_mlp=310 after [sw_decoder]
#      Both are written to /var/lib/webosbrew/truehd/ and bind-mounted by the
#      boot hook (originals are never modified in place - fully reversible).
#   4. Installs the canonical init_dts25.sh, then runs its READ-ONLY compatibility
#      preflight (W25_CHECK=1). Only if that says verified/forced does it symlink
#      the boot hook /var/lib/webosbrew/init.d/restore_dts25 -> it. On any other
#      verdict it prints the reason and changes nothing on this TV.
#   5. Applies everything now (runs the init script) + restarts the media pipe.
#
# COMPATIBILITY GATE. Our .so are bind-mounted over LG's system-wide (they
# propagate into every app jail), so this installer refuses to bind on a TV whose
# stock plugin fingerprints are not in init_dts25.sh's verified-sets table. To
# opt in anyway on an unverified TV:
#
#   FORCE=1 sh install.sh
#
# which is recorded as forced=1 in /var/lib/webosbrew/dts25/stock.fp so later
# boots honour the choice. FORCE=1 NEVER overrides a drift verdict (the stock
# plugins changed under an existing install) or the GStreamer ABI guard or the
# loader gate. To re-opt-in after a firmware change, run uninstall.sh (which
# clears the recorded baseline) and then install.sh, which puts the TV back in
# the unverified flow where the opt-in applies.
#
# A REFUSED RUN LEAVES THE STAGED FILES UNDER /var/lib/webosbrew IN PLACE, on
# purpose: no boot hook is linked, so they are inert, and stock.fp among them is
# what lets a later run distinguish a firmware change from an unverified TV. Use
# uninstall.sh to remove them.
#
set -u

# Explicit opt-in on a TV that is not in the verified-sets table. Author-read
# only: the value is compared, never interpolated into a command.
FORCE=${FORCE:-0}

LOG=/tmp/dts25.log
DTS_DEST=/var/lib/webosbrew/dts25
THD_DEST=/var/lib/webosbrew/truehd
THD_LIBS=$THD_DEST/libs
INITD=/var/lib/webosbrew/init.d
HOOK=$INITD/restore_dts25
INIT_SCRIPT=$DTS_DEST/init_dts25.sh
# Marker that says "an SSH/CLI install owns this state", so the boot script's
# self-heal does not mistake a CLI-only install for an orphaned one.
CLI_MARKER=$DTS_DEST/.cli-install

# Live LG config files we derive our (bind-mounted) overrides from.
CFG_LIVE=/etc/umediaserver/device_codec_capability_config.json
CFG_OVR=$THD_DEST/codec_capability.json
GC_LIVE=/etc/gst/gstcool.conf
GC_OVR=$THD_DEST/gstcool.conf

# Bind targets the boot hook manages (unmount here so we read pristine originals).
LGLIBAV=/usr/lib/gstreamer-1.0/libgstlibav.so
REG_TARGET=/mnt/flash/data/gst_1_0_registry.arm.bin
# The app-DTS opt-in bind (tv.model.edidType); see the APPLY 2d block in
# init_dts25.sh for why it is a separate opt-in.
# NOTE the /tmp path, not /var/run: /var/run is a symlink to /tmp/var/run, so a
# bind made here is recorded in /proc/mounts under the RESOLVED path. Writing
# /var/run/... would make every "is it already mounted" guard miss -- stacking a
# fresh mount on every run and never unmounting on Disable.
LLS_LIVE=/tmp/var/run/tvconfig/lls/factorydb.json

SELF_DIR=$(cd "$(dirname "$0")" && pwd)

log() { echo "[dts25-install $(date '+%Y-%m-%d %H:%M:%S')] $*" >> "$LOG" 2>&1; }

# Unmount one bind target, falling back to a LAZY detach when it is busy.
# Measured on a real C5: umount of /usr/lib/gstreamer-1.0/libgstlibav.so fails
# with "target is busy" because WebAppMgr has the .so mapped, while `umount -l`
# succeeds -- so without this fallback a stale override survives the "regenerate
# from pristine originals" step and we would derive our overrides from OUR OWN
# files. Same semantics as w25_umount() in init_dts25.sh.
w25_umount() {
  grep -q " $1 " /proc/mounts 2>/dev/null || return 0
  if umount "$1" 2>>"$LOG"; then log "unmounted stale bind $1"; return 0; fi
  if umount -l "$1" 2>>"$LOG"; then log "lazy-detached busy stale bind $1 (a live mapping held it)"; return 0; fi
  log "WARN could not unmount $1, even lazily"
  return 1
}

log "=== unified DTS+TrueHD install start ==="

# --- 1. Stage DTS payload --------------------------------------------------
# dtsdec links its decoder statically, so nothing goes into dts25/libs/ any
# more. A libdca.so.0 left there by an older install is inert (nothing NEEDS
# it) and is removed with the rest of dts25/ by uninstall.sh.
mkdir -p "$DTS_DEST" || { log "FATAL: cannot create $DTS_DEST"; exit 0; }

# Mark this as an SSH/CLI install BEFORE anything can run the boot script: its
# self-heal reverts an install that no longer has an owner (app dir gone), and
# without this marker a CLI-only install would look exactly like that and be
# healed away on the next boot.
: > "$CLI_MARKER" && log "marked CLI install ($CLI_MARKER)" || log "WARN: could not write $CLI_MARKER"

if [ -f "$SELF_DIR/out/libgstdtsdec.so" ]; then
  cp -f "$SELF_DIR/out/libgstdtsdec.so" "$DTS_DEST/libgstdtsdec.so" \
    && log "installed libgstdtsdec.so -> $DTS_DEST/" || log "WARN: copy libgstdtsdec.so failed"
else
  log "WARN: $SELF_DIR/out/libgstdtsdec.so not found (run build.sh first)"
fi

# --- 1b. Stage the adecswitch payload (track A: same-family stream-switch bin,
#         compiled rank 320) into the same dts25 dir the plugin path already
#         covers -- CORE, like dtsdec/libav (init_dts25.sh w25_core_staged).
if [ -f "$SELF_DIR/switch-out/libgstadecswitch.so" ]; then
  cp -f "$SELF_DIR/switch-out/libgstadecswitch.so" "$DTS_DEST/libgstadecswitch.so" \
    && log "installed libgstadecswitch.so -> $DTS_DEST/" || log "WARN: copy libgstadecswitch.so failed"
else
  log "WARN: $SELF_DIR/switch-out/libgstadecswitch.so not found (run build-switch.sh first)"
fi
# The eim hook for "Show DTS tracks in apps" (init_dts25.sh w25_hdmi_hook_on).
# Optional: without it the HDMI inputs list DTS while that opt-in is on.
if [ -f "$SELF_DIR/edid-out/libedidaudio.so" ]; then
  cp -f "$SELF_DIR/edid-out/libedidaudio.so" "$DTS_DEST/libedidaudio.so" \
    && log "installed libedidaudio.so -> $DTS_DEST/" || log "WARN: copy libedidaudio.so failed"
fi

# --- 1c. Stage the eARC ALSA check/recovery helper (never rewires DSP edges).
if [ -f "$SELF_DIR/out/lgroute-control" ]; then
  cp -f "$SELF_DIR/out/lgroute-control" "$DTS_DEST/lgroute-control" \
    && chmod 0755 "$DTS_DEST/lgroute-control" \
    && log "installed lgroute-control -> $DTS_DEST/" || log "WARN: staging lgroute-control failed"
else
  log "note: out/lgroute-control absent; DTS-HD passthrough unavailable"
fi

# --- 2. Stage TrueHD payload (preserve the .so version symlinks) -----------
mkdir -p "$THD_LIBS" || { log "FATAL: cannot create $THD_LIBS"; exit 0; }

if [ -f "$SELF_DIR/truehd-out/libgstlibav.so" ]; then
  cp -f "$SELF_DIR/truehd-out/libgstlibav.so" "$THD_DEST/libgstlibav.so" \
    && log "installed libgstlibav.so -> $THD_DEST/" || log "WARN: copy libgstlibav.so failed"
else
  log "WARN: $SELF_DIR/truehd-out/libgstlibav.so not found (run build-truehd.sh first)"
fi

n=0
for f in "$SELF_DIR"/truehd-out/libav*.so* "$SELF_DIR"/truehd-out/libsw*.so*; do
  [ -e "$f" ] || continue
  # cp -P preserves the soname symlinks (libavcodec.so.58 -> libavcodec.so.58.x.y).
  cp -Pf "$f" "$THD_LIBS/" && n=$((n+1))
done
log "staged $n ffmpeg lib entries -> $THD_LIBS/"

# --- 2c. Stage container-demuxer payload (mp4/ts/m2ts DTS re-enabled) -------
# Patched isomp4/mpegtsdemux (dts_support default TRUE) and matroska (Dolby
# Vision profile 7). Optional: if demux-out/ is absent the boot hook simply skips
# the demuxer binds (MKV DTS still works).
DMX_DEST=/var/lib/webosbrew/demux25
DMX_ISO=/usr/lib/gstreamer-1.0/libgstisomp4.so
DMX_TSD=/usr/lib/gstreamer-1.0/libgstmpegtsdemux.so
DMX_MKV=/usr/lib/gstreamer-1.0/libgstmatroska.so
DMX_PSD=/usr/lib/gstreamer-1.0/libgstmpegpsdemux.so
mkdir -p "$DMX_DEST" || log "WARN: cannot create $DMX_DEST"
for so in libgstisomp4.so libgstmpegtsdemux.so libgstmatroska.so libgstmpegpsdemux.so; do
  if [ -f "$SELF_DIR/demux-out/$so" ]; then
    cp -f "$SELF_DIR/demux-out/$so" "$DMX_DEST/$so" \
      && log "installed $so -> $DMX_DEST/" || log "WARN: copy $so failed"
  else
    log "note: $SELF_DIR/demux-out/$so not found; its demuxer override will be skipped"
  fi
done

# --- 2d. Seed first-run audio defaults (make-up gain + DRC) -----------------
# Gain and DRC shipped OPT-IN while the DSP was still unproven: no config file
# meant fully inert (0.0 dB, DRC off), so an install could not change anyone's
# sound. Now that the curve is validated on-device, that caution costs more
# than it buys - an untouched install leaves DTS/TrueHD quieter and
# un-managed next to native AAC/AC-3, which is what the feature exists to fix.
# So seed a starting point and let users tune down instead of discovering they
# have to tune up.
# Written ONLY when absent: after the first install the file belongs to the
# user (the app's Save owns it), and re-running install.sh must never
# clobber their settings. Retune from the app or per TUNING-RUNBOOK.md.
# NOTE: keep in sync with the app's w25GainConfSeedScript() (CLAUDE.md rule 3).
# The +5.0 dB is not a guess: it is the value the maintainer arrived at BY EAR
# on a real C5, with this same DRC line 100/100 preset active, and has been
# running as a hand-set config. Prefer that over a theoretical figure.
seed_gain_conf() {
  if [ -f "$1" ]; then
    log "note: $1 exists; keeping saved audio settings"
  elif printf '%s\n%s\n%s\n%s\n%s\n' \
      "5.0" "drc=line" "drc_boost=100" "drc_cut=100" "center=0.0" \
      > "$1.tmp" && mv -f "$1.tmp" "$1"; then
    log "seeded first-run audio defaults -> $1 (+5.0 dB, DRC line 100/100)"
  else
    log "WARN: could not seed $1"
  fi
}
seed_gain_conf "$DTS_DEST/gain.conf"
seed_gain_conf "$THD_DEST/gain.conf"

awk '/^INIT_B64$/{exit} emit{print} /^base64 -d >.*INIT_B64/{emit=1}' "$0" | base64 -d | W25_PT=stop sh || exit 1
if [ "${HD:-0}" = 1 ]; then
  [ -x "$DTS_DEST/lgroute-control" ] || { echo 'ERROR=The eARC helper is missing; DTS-HD settings were kept.'; exit 1; }
  : > "$DTS_DEST/passthrough" && : > "$DTS_DEST/passthrough-hd" \
    && log "opted in to DTS-HD passthrough"
fi

# --- 3. Unmount any existing binds so we regenerate from PRISTINE originals -
# This also has to leave the stock plugins we shadow unshadowed, because the
# compatibility preflight in step 4b fingerprints them straight after.
for T in "$CFG_LIVE" "$GC_LIVE" "$LGLIBAV" "$DMX_ISO" "$DMX_TSD" "$DMX_MKV" "$DMX_PSD" "$REG_TARGET" "$LLS_LIVE"; do
  w25_umount "$T"
done

# --- 3a. Generate the codec-capability override (insert TRUEHD+MLP after DTSE)
# awk is idempotent: it only injects when the DTSE object is seen and, guarded
# below, only when TRUEHD is not already present in the source.
if [ -f "$CFG_LIVE" ]; then
  if grep -q '"TRUEHD"' "$CFG_LIVE"; then
    log "note: live capability config already has TRUEHD; copying as-is"
    cp -f "$CFG_LIVE" "$CFG_OVR"
  else
    awk '
      /"name" : "DTSE"/ { indts=1 }
      { print }
      indts && /^ *},/ {
        print "    {";
        print "      \"name\" : \"TRUEHD\",";
        print "      \"channels\" : 8";
        print "    },";
        print "";
        print "    {";
        print "      \"name\" : \"MLP\",";
        print "      \"channels\" : 8";
        print "    },";
        indts=0
      }
    ' "$CFG_LIVE" > "$CFG_OVR" && log "generated capability override $CFG_OVR (TRUEHD+MLP after DTSE)" \
      || log "WARN: capability override generation failed"
  fi
else
  log "WARN: $CFG_LIVE not present; cannot generate capability override"
fi

# --- 3b. Generate the gstcool.conf override (avdec_truehd/mlp=310 +
#         adecswitch=320 rank levers; adecswitch is also a config-level kill
#         switch for track A -- rank 0 reverts to stock decodebin3 behaviour)
if [ -f "$GC_LIVE" ]; then
  if grep -q '^avdec_truehd=' "$GC_LIVE"; then
    log "note: live gstcool.conf already has avdec_truehd; copying as-is"
    cp -f "$GC_LIVE" "$GC_OVR"
  else
    awk '
      { print }
      /^\[sw_decoder\]/ { print "avdec_truehd=310"; print "avdec_mlp=310"; print "adecswitch=320" }
    ' "$GC_LIVE" > "$GC_OVR" && log "generated gstcool override $GC_OVR (avdec_truehd/mlp=310, adecswitch=320)" \
      || log "WARN: gstcool override generation failed"
  fi
else
  log "WARN: $GC_LIVE not present; cannot generate gstcool override"
fi

# --- 4. Install the canonical boot/apply script (embedded) + hook ----------
# The boot/apply logic is embedded here as base64 so this installer is a single
# self-contained script (no sibling init file needed). Decodes verbatim to the
# proven init_dts25.sh.
base64 -d > "$INIT_SCRIPT" <<'INIT_B64'

INIT_B64
chmod 0755 "$INIT_SCRIPT" && log "installed embedded init_dts25.sh -> $INIT_SCRIPT" || log "WARN: writing init_dts25.sh failed"

# --- 4b. Compatibility preflight (READ-ONLY) -------------------------------
# Run the gate that init_dts25.sh enforces, in its check mode: it fingerprints
# the three stock plugins we shadow (pristine, thanks to step 3), matches them
# against the verified-sets table, and confirms every payload object's dynamic
# dependencies resolve on THIS TV. Only one authored copy of that gate exists --
# this asks the installed script rather than duplicating it here.
#
# Nothing is bound until this passes and the boot hook is not linked at all, so a
# refusal never APPLIES anything (the staged files under /var/lib/webosbrew are
# inert without the binds). It is not a no-op on a TV that was already enabled,
# though: step 3 above has already detached the binds, and our `cp -f` registry
# would still be live. Every refusal branch below therefore stands the TV down --
# W25_STAND_DOWN=1 rebuilds LG's registry if one of ours is in place -- so the TV
# ends up on stock rather than half-way.
CHECK=$(W25_CHECK=1 FORCE="$FORCE" sh "$INIT_SCRIPT" 2>/dev/null)
GATE_VERDICT=$(printf '%s\n' "$CHECK" | sed -n 's/^VERDICT=//p' | head -n1)
GATE_REASON=$(printf '%s\n' "$CHECK" | sed -n 's/^REASON=//p' | head -n1)
GATE_LABEL=$(printf '%s\n' "$CHECK" | sed -n 's/^LABEL=//p' | head -n1)
GATE_CANFORCE=$(printf '%s\n' "$CHECK" | sed -n 's/^CANFORCE=//p' | head -n1)
GATE_LOADER=$(printf '%s\n' "$CHECK" | sed -n 's/^LOADER=//p' | head -n1)
GATE_STAGED=$(printf '%s\n' "$CHECK" | sed -n 's/^LOADER_STAGED=//p' | head -n1)
log "preflight: verdict=$GATE_VERDICT canforce=$GATE_CANFORCE loader=$GATE_LOADER staged=$GATE_STAGED reason=$GATE_REASON"

# Put the TV back on stock before reporting a refusal. Step 3 already detached the
# binds, so on a previously-enabled TV the only thing left applied is the `cp -f`
# registry -- which W25_STAND_DOWN=1 rebuilds from LG's own plugins. Prints
# STOOD_DOWN=1 when a registry of ours was actually live.
stand_down_now() {
  SD=$(W25_STAND_DOWN=1 sh "$INIT_SCRIPT" 2>/dev/null)
  log "stand-down: $(printf '%s' "$SD" | tr '\n' ' ')"
  case "$SD" in
    *STOOD_DOWN=1*)
      echo "This TV was previously enabled, so the overrides have been REVERTED:"
      echo "the bind-mounts are detached and LG's plugin registry has been restored." ;;
    *)
      echo "Nothing of ours was applied on this TV, and nothing was changed." ;;
  esac
}

if [ "$GATE_LOADER" != "ok" ]; then
  # LOADER_STAGED=0 means the CORE payload is not staged (out/ or truehd-out/
  # missing or not copied) -- a packaging problem, not an incompatible TV. A
  # demux-less staging is NOT this case: the gate skips optional objects.
  if [ "$GATE_STAGED" = 0 ]; then
    log "REFUSED: core payload incomplete -- $GATE_LOADER"
    echo "DTS + TrueHD install REFUSED: the core payload is incomplete."
    echo "  $GATE_LOADER"
    echo "Check that out/ and truehd-out/ are populated (see the header of this script)."
  else
    log "REFUSED: loader gate -- $GATE_LOADER"
    echo "DTS + TrueHD install REFUSED: the payload cannot load on this TV."
    echo "  $GATE_LOADER"
  fi
  stand_down_now
  echo "See $LOG for details."
  exit 0
fi

case "$GATE_VERDICT" in
  verified)
    log "gate: verified TV -- $GATE_LABEL"
    echo "Verified TV: $GATE_LABEL"
    ;;
  forced)
    log "gate: forced apply on an unverified TV -- $GATE_REASON"
    echo "WARNING: this TV is not on the verified list; applying anyway (FORCE=1)."
    ;;
  drift)
    # A firmware change that touches the plugins we shadow stands us down, full
    # stop -- FORCE=1 does not apply here, so it is not offered. What DOES work is
    # clearing the recorded baseline (uninstall.sh) and opting in through the
    # unverified flow, or getting this TV added to the verified table.
    log "REFUSED: drift -- $GATE_REASON"
    echo "DTS + TrueHD install REFUSED: this TV changed since it was last verified."
    echo "  $GATE_REASON"
    echo ""
    stand_down_now
    echo "FORCE=1 does not override this."
    echo "To opt in again explicitly:  sh uninstall.sh  &&  FORCE=1 sh install.sh"
    echo "Or report these fingerprints so this TV can be added to the verified table:"
    printf '%s\n' "$CHECK" | sed -n 's/^PRODUCT_ID=/    product_id=/p;s/^WEBOS_RELEASE=/    webos_release=/p;s/^GST_MM=/    gst_mm=/p;s/^MD5_LIBGSTLIBAV=/    libgstlibav=/p;s/^MD5_LIBGSTISOMP4=/    libgstisomp4=/p;s/^MD5_LIBGSTMPEGTSDEMUX=/    libgstmpegtsdemux=/p;s/^MD5_LIBGSTMATROSKA=/    libgstmatroska=/p;s/^MD5_DEVICE_CODEC_CAPABILITY_CONFIG=/    device_codec_capability_config=/p;s/^MD5_GSTCOOL=/    gstcool=/p'
    echo "See $LOG for details."
    exit 0
    ;;
  *)
    log "REFUSED: $GATE_VERDICT -- $GATE_REASON"
    echo "DTS + TrueHD install REFUSED: $GATE_REASON"
    if [ "$GATE_CANFORCE" = 1 ]; then
      # unverified only -- drift is handled above and reports CANFORCE=0.
      echo "The payload's libraries DO resolve on this TV. To opt in anyway:"
      echo "    FORCE=1 sh install.sh"
    fi
    stand_down_now
    echo "See $LOG for details."
    exit 0
    ;;
esac

# --- 4c. Link the boot hook (only now that the gate has passed) -------------
mkdir -p "$INITD"
if [ -L "$HOOK" ] || [ -e "$HOOK" ]; then rm -f "$HOOK"; fi
ln -s "$INIT_SCRIPT" "$HOOK" && log "linked boot hook $HOOK -> $INIT_SCRIPT"

# --- 5. Apply now ----------------------------------------------------------
# The init script re-runs the same gate, writes stock.fp from the pristine
# fingerprints, binds, and commits the registry only if all five elements
# (dtsdec, avdec_truehd, qtdemux, tsdemux, matroskademux) survive the binds.
log "applying now (running $INIT_SCRIPT)"
# W25_NO_APPDTS: installing leaves the app-DTS opt-in to the boot hook and the
# app's toggle (see "App DTS opt-in" in init_dts25.sh).
APPLY=$(W25_NO_APPDTS=1 FORCE="$FORCE" sh "$INIT_SCRIPT" 2>/dev/null)
log "apply result: $(printf '%s' "$APPLY" | tr '\n' ' ')"

case "$APPLY" in
  *ERROR=*)
    printf '%s\n' "$APPLY"
    exit 1
    ;;
  *REFUSED=*)
    echo "DTS + TrueHD install did NOT apply:"
    printf '%s\n' "$APPLY" | sed -n 's/^REASON=/  /p'
    echo "The boot hook has been left in place; it re-checks on every boot and"
    echo "binds nothing until the TV passes. See $LOG for details."
    ;;
  *)
    if killall starfish-media-pipeline 2>>"$LOG"; then
      log "restarted starfish-media-pipeline"
    else
      log "note: starfish-media-pipeline not running (starts fresh on next playback)"
    fi
    echo "DTS + TrueHD install complete. See $LOG for details."
    ;;
esac

log "=== unified DTS+TrueHD install done ==="
exit 0
